// The MCP tool reference (MH-428): GET /api/mcp/docs, generated by the API from its own tool
// registry (internal/mcp/docs.go), so this page cannot drift from what the server offers.

export type McpDocArg = {
  name: string
  type: string
  required: boolean
  description?: string
  enum?: (string | number)[]
}

export type McpDocTool = {
  name: string
  description: string
  scope: string
  min_role: string
  writes: boolean
  arguments: McpDocArg[]
  input_schema: Record<string, unknown>
  example_call: Record<string, unknown>
  example_result: string
}

export type McpDocGroup = { id: string; title: string; intro: string; tools: McpDocTool[] }

export type McpDocScope = { scope: string; description: string; min_role: string; tools: string[] }

export type McpDocsCatalog = {
  lang: string
  /**
   * The one URL to connect to, straight from the API's MCPServerURL()
   * (internal/mcp/oauth.go): the dedicated mcp.<domain> host once
   * MCP_PUBLIC_URL names one (MH-516), else this app's own /api/mcp. There is
   * no client-side fallback for this any more — the API is the single source,
   * the same one Settings' server_url field reads (MH-428/MH-516).
   */
  server_url: string
  /** The app's own /api/mcp when server_url is elsewhere (mcp.moharrik.com): still works for older connections. */
  legacy_url?: string
  protocol_versions: string[]
  tool_count: number
  roles: string[]
  scopes: McpDocScope[]
  groups: McpDocGroup[]
}

/** The public path of the docs, for links from the app. */
export function mcpDocsHref(locale: string, anchor?: string) {
  return `/${locale}/docs/mcp${anchor ? `#${anchor}` : ""}`
}

// The permission explainer (MH-1069): GET /api/mcp/permissions, derived by the API from the
// same tool registry (internal/mcp/permissions.go). Nothing here is a frontend-side list.
export type McpPermTool = { name: string; summary: string; confirm?: string }

export type McpPermScope = {
  scope: string
  description: string
  min_role: string
  can_read: McpPermTool[]
  can_change: McpPermTool[]
  needs_confirm: McpPermTool[]
}

export type McpPermissions = {
  lang: string
  tool_count: number
  scopes: McpPermScope[]
  never: { id: string; label: string }[]
}
